SELECT * FROM mt_rider_order
WHERE RIDER_ID = #{riderId}

    AND STATUS IN

        #{status}


ORDER BY CREATE_TIME DESC

SELECT
    COUNT(*) as deliveryCount,
    COUNT(DISTINCT DATE(CREATE_TIME)) as workDays,
    IFNULL(SUM(DELIVERY_FEE), 0) as totalIncome
FROM mt_rider_order
WHERE RIDER_ID = #{riderId}
  AND STATUS IN ('M', 'N', 'F', 'I')
  AND CREATE_TIME >= #{beginTime}
  AND CREATE_TIME <= #{endTime}

SELECT IFNULL(SUM(DELIVERY_FEE), 0)
FROM mt_rider_order
WHERE RIDER_ID = #{riderId}
  AND STATUS IN ('M', 'N', 'F', 'I')
  AND CREATE_TIME >= #{beginTime}
  AND CREATE_TIME <= #{endTime}

SELECT
    DATE(CREATE_TIME) as date,
    COUNT(*) as count
FROM mt_rider_order
WHERE RIDER_ID = #{riderId}
  AND CREATE_TIME >= #{beginTime}
  AND CREATE_TIME <= #{endTime}
GROUP BY DATE(CREATE_TIME)
ORDER BY date ASC

SELECT
    DATE(CREATE_TIME) as date,
    IFNULL(SUM(DELIVERY_FEE), 0) as income
FROM mt_rider_order
WHERE RIDER_ID = #{riderId}
  AND STATUS IN ('M', 'N', 'F', 'I')
  AND CREATE_TIME >= #{beginTime}
  AND CREATE_TIME <= #{endTime}
GROUP BY DATE(CREATE_TIME)
ORDER BY date ASC
